(()=>{'use strict';const $=s=>document.querySelector(s),world=$('#world'),dig=$('#dig'),dump=$('#dump'),hint=$('#tapHint');let started=false,loaded=false,count=0,busy=false,muted=false,ac;try{muted=localStorage.getItem('littleHandsMuted')==='true'}catch{}const timers=new Set();function later(fn,ms){const id=setTimeout(()=>{timers.delete(id);fn()},ms);timers.add(id)}function tone(f){if(muted)return;try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();ac.resume();const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(f,ac.currentTime);o.frequency.exponentialRampToValueAtTime(f*1.3,ac.currentTime+.16);g.gain.setValueAtTime(.08,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.35);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.36)}catch{}}function say(t){if(muted||!window.speechSynthesis)return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='zh-CN';u.rate=.82;speechSynthesis.speak(u)}function sound(){const b=$('#sound');b.textContent=muted?'♪':'♫';b.setAttribute('aria-pressed',String(muted));b.setAttribute('aria-label',muted?'打开声音':'关闭声音')}function render(){world.classList.toggle('loaded',loaded);world.classList.toggle('done',count===3);dig.hidden=!started||loaded||count===3;dump.hidden=!started||!loaded;dig.disabled=busy;dump.disabled=busy;hint.style.display=!started||busy||count===3?'none':'';hint.setAttribute('transform',loaded?'translate(745 418)':'translate(500 528)');$('#pile').style.transform=`scale(${1-count*.22})`;for(let i=1;i<=3;i++)$('#load'+i).style.opacity=count>=i?'1':'0';document.querySelectorAll('.dots i').forEach((d,i)=>d.classList.toggle('filled',i<count));$('#status').textContent=count===3?'小车出发，花儿开啦！':loaded?'点点车厢，装一装。':'点点沙堆，挖一挖。'}function reset(){timers.forEach(clearTimeout);timers.clear();if(window.speechSynthesis)speechSynthesis.cancel();started=true;loaded=false;count=0;busy=false;world.classList.remove('dumping');$('#welcome').hidden=true;render();say('点点沙堆，挖一挖')}$('#start').onclick=reset;$('#replay').onclick=reset;dig.onclick=()=>{if(!started||loaded||busy||count===3)return;busy=true;loaded=true;tone(170);render();later(()=>{busy=false;render();say('挖到啦！点点车厢，装一装')},700)};dump.onclick=()=>{if(!loaded||busy)return;busy=true;loaded=false;count++;tone(370);render();world.classList.add('dumping');if(count===3)say('装好啦！小车出发，谢谢小帮手');else say('再挖一铲吧');later(()=>{busy=false;world.classList.remove('dumping');render()},700)};$('#sound').onclick=()=>{muted=!muted;if(muted&&window.speechSynthesis)speechSynthesis.cancel();try{localStorage.setItem('littleHandsMuted',String(muted))}catch{}sound();if(!muted)tone(400)};document.addEventListener('visibilitychange',()=>{if(document.hidden&&window.speechSynthesis)speechSynthesis.cancel()});sound();render()})();
